{
  "feature": "SQL JOIN: customer_id relationship",
  "category": "normal",
  "precondition": {
    "schema": [{"table": "customers", "columns": [{"name": "customer_id", "type": "text"}, {"name": "company_name", "type": "text"}]}, {"table": "orders", "columns": [{"name": "order_id", "type": "int"}, {"name": "customer_id", "type": "text"}]}],
    "data": {"customers": [["ALFKI", "Alfreds Futterkiste"], ["FISSA", "FISSA BV"], ["PARIS", "Paris spécialités"]], "orders": [["10248", "ALFKI"], ["10249", "FISSA"], ["10250", "PARIS"]]},
    "config": [],
    "session_state": null
  },
  "behavior_under_test": {
    "description": "Test the left join from customers to orders to ensure a customer with no matching orders returns with order_count = 0.",
    "sql_sketch": "SELECT c.customer_id, c.company_name, COUNT(o.order_id) AS order_count FROM customers c LEFT JOIN orders o ON c.customer_id = o.customer_id GROUP BY c.customer_id, c.company_name",
    "property": "The result should include all customers, with order_count = 0 for those with no orders."
  },
  "expected_result": {
    "kind": "result_set",
    "assertions": ["ALFKI Alfreds Futterkiste 6", "FISSA FISSA BV 1", "PARIS Paris spécialités 1"],
    "order_sensitive_rows": false
  },
  "evidence": [{"chunk": "requirement_test#req1", "span": "\"A customer with no matching orders remains in the result with order_count = 0."}, {"chunk": "requirement_test#req1", "span": "\"Several matching order rows produce one customer row and count each order exactly once."}, {"chunk": "requirement_test#req1", "span": "\"An absent customer_id returns no row and does not synthesize a customer or order count."}]
}

